var i=`0050-vepro-knedlo-zelo`;var t=`world-0050`;var a=`CZ`;var o=`eastern-europe`;var s=4;var r=137;var l={en:`Vepřo Knedlo Zelo`,ua:`Свинина з кнедликами та капустою`};var g={en:`A classic dish from Czechia, featuring pork shoulder, garlic, yellow onion, sauerkraut. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Чехія. Основні складники: свиняча лопатка, часник, жовта цибуля, квашена капуста. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 15 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 15 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:15,i:[[`pork-shoulder`,800,`g`],[`lard`,40,`g`],[`garlic`,4,`clove`],[`caraway-seeds`,5,`g`],[`table-salt`,null,`to_taste`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 80 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 80 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:80,i:[[`water`,300,`ml`],[`yellow-onion`,150,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`sauerkraut`,500,`g`],[`white-granulated-sugar`,12,`g`]]},{en:`Cook dumplings in batches in gently boiling salted water for about 15 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 15 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:15,i:[[`potato-dumplings`,400,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,12,`g`]]}];var u={slug:i,id:t,country:`CZ`,region:o,servings:4,minutes:137,title:l,text:g,steps:d};export{a as country,u as default,t as id,r as minutes,o as region,s as servings,i as slug,d as steps,g as text,l as title};